// <auto-generated-scaffold>
//   HAND-WRITTEN. Mechanism C: we call them, on a clock, and remember where we got to.
// </auto-generated-scaffold>
#nullable enable

using Marten;
using Wolverine;
using StockFeed.Contracts;   // StockNoticed — the model-declared foreign event

namespace StockFeed.Landing;

/// <summary>
/// The warehouse as seen from our side. An interface rather than an HttpClient call because the far side is
/// the one thing a reference implementation cannot honestly own — and because it makes the mechanism testable
/// without a second process. In production this wraps their API; here a test pushes notices into a stub.
/// </summary>
public interface IWarehouseFeed
{
    /// <summary>Notices with a sequence strictly greater than <paramref name="afterSequence"/>, oldest first.</summary>
    Task<IReadOnlyList<StockNoticed>> NoticesAfter(long afterSequence, CancellationToken cancellation);
}

/// <summary>
/// WHERE WE GOT TO, and it is a document we own rather than anything the warehouse knows about. This is the
/// entire structural difference between a pull feed and a push feed: a push feed's position is implicit in
/// what has arrived, and needs no storage, no migration and no operator who understands it.
/// </summary>
public sealed record FeedCheckpoint
{
    public const string TheOne = "warehouse";
    public string Id { get; init; } = TheOne;
    public long Sequence { get; init; }
}

/// <summary>
/// MECHANISM C: a clock, and nothing more — the same shape as the automation folder's SweepClock, and for
/// the same reasons. A plain loop rather than a durable self-rescheduling message, because six attempts at
/// the latter failed silently on this stack and it buys nothing here: the durable state is the checkpoint
/// plus whatever the warehouse still has, not a message in flight.
///
/// IHostedLifecycleService, not IHostedService: StartedAsync runs after every hosted service has started, so
/// Wolverine and the Marten schema are both up before the first poll.
/// </summary>
public sealed class WarehousePollClock(IServiceProvider services) : IHostedLifecycleService, IAsyncDisposable
{
    private readonly CancellationTokenSource _stopping = new();
    private Task? _loop;

    public static readonly TimeSpan Interval = TimeSpan.FromSeconds(
        double.TryParse(Environment.GetEnvironmentVariable("FEED_POLL_SECONDS"), out var s) ? s : 5);

    public Task StartedAsync(CancellationToken cancellation)
    {
        _loop = RunAsync();
        return Task.CompletedTask;     // must return, or the host never finishes starting
    }

    private async Task RunAsync()
    {
        var logger = services.GetRequiredService<ILoggerFactory>().CreateLogger<WarehousePollClock>();

        // Poll immediately and then on the interval. A PeriodicTimer waits first, which for a pull feed means
        // the app is knowingly stale for one whole interval after every deploy — and made the first version
        // of this class look dead when it was merely early.
        do
        {
            try
            {
                await PollOnce(logger, _stopping.Token);
            }
            catch (OperationCanceledException) when (_stopping.IsCancellationRequested) { return; }
            catch (Exception e)
            {
                // One failed poll must never kill the clock. The checkpoint has not moved, so the next tick
                // re-reads the same notices and recovery is automatic — which is only true because ingest is
                // idempotent. A clock that dies on a transient error is indistinguishable from one that has
                // caught up.
                logger.LogError(e, "warehouse poll failed. Continuing.");
            }

            try { await Task.Delay(Interval, _stopping.Token); }
            catch (OperationCanceledException) { return; }
        }
        while (!_stopping.IsCancellationRequested);
    }

    private async Task PollOnce(ILogger logger, CancellationToken cancellation)
    {
        await using var scope = services.CreateAsyncScope();
        var store = scope.ServiceProvider.GetRequiredService<IDocumentStore>();
        var feed = scope.ServiceProvider.GetRequiredService<IWarehouseFeed>();
        var bus = scope.ServiceProvider.GetRequiredService<IMessageBus>();

        long from;
        await using (var query = store.QuerySession())
        {
            from = (await query.LoadAsync<FeedCheckpoint>(FeedCheckpoint.TheOne, cancellation))?.Sequence ?? 0;
        }

        var notices = await feed.NoticesAfter(from, cancellation);
        if (notices.Count == 0)
        {
            // LOG A POLL THAT FOUND NOTHING. Otherwise "up to date" and "dead" are byte-identical in the log,
            // and that ambiguity has already hidden one broken mechanism in this kit.
            logger.LogInformation("warehouse poll: nothing after sequence {From}.", from);
            return;
        }

        var highest = from;
        foreach (var notice in notices)
        {
            // Awaited one at a time, in order. Notices for one product must not race each other: the decider
            // would refuse the loser as stale, which is correct and wasteful.
            await bus.InvokeAsync(notice, cancellation);
            highest = Math.Max(highest, notice.Sequence);
        }

        // ADVANCE AFTER, NEVER BEFORE. A crash between the ingest and this write re-reads notices we already
        // hold, and the domain dedupe discards them. A crash after advancing but before ingesting would lose
        // them for good — and from a feed that never re-sends, "for good" means a permanently wrong stock
        // level, which is exactly the harm the slice exists to prevent.
        await using var session = store.LightweightSession();
        session.Store(new FeedCheckpoint { Sequence = highest });
        await session.SaveChangesAsync(cancellation);

        logger.LogInformation(
            "warehouse poll: {Count} notice(s) after sequence {From}; checkpoint now {Highest}.",
            notices.Count, from, highest);
    }

    public async Task StoppingAsync(CancellationToken cancellation)
    {
        await _stopping.CancelAsync();
        if (_loop is not null) await _loop.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
    }

    public async ValueTask DisposeAsync()
    {
        await StoppingAsync(CancellationToken.None);
        _stopping.Dispose();
    }

    public Task StartingAsync(CancellationToken cancellation) => Task.CompletedTask;
    public Task StartAsync(CancellationToken cancellation) => Task.CompletedTask;
    public Task StopAsync(CancellationToken cancellation) => Task.CompletedTask;
    public Task StoppedAsync(CancellationToken cancellation) => Task.CompletedTask;
}
